G=load()
# Rule guess: read T from input's topmost nonzero row (left→right, skipping trailing zeros),
# out(r,c) = T[max(r,c) % L] — validated on demo3. Check demo1 & demo2 under vertical/horizontal flips.
def solve(inp, mode='max'):
    H=len(inp); W=len(inp[0])
    # find topmost row containing nonzero
    top=[r for r in range(H) if any(inp[r][c] for c in range(W))]
    tr=top[0]
    T=[inp[tr][c] for c in range(W) if inp[tr][c]]
    L=len(T); OH,OW=2*H,2*W
    res=[[0]*OW for _ in range(OH)]
    if mode=='max':
        for r in range(OH):
            for c in range(OW):
                res[r][c]=T[(max(r,c))%L]
    elif mode=='mincr':
        for r in range(OH):
            for c in range(OW):
                res[r][c]=T[(min(c,OH-1-r))%L]
    elif mode=='minrc':
        for r in range(OH):
            for c in range(OW):
                res[r][c]=T[(min(r,OW-1-c))%L]
    return res
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
