def seq_of(inp):
    H=len(inp);W=len(inp[0]);top=min(r for r in range(H) if any(inp[r][c] for c in range(W)))
    bottom=max(r for r in range(H) if any(inp[r][c] for c in range(W)))
    right=max(c for c in range(W) if any(inp[r][c] for r in range(H)))
    # anti-diagonal through bbox corner (bottom,right) stepping up-left
    seq=[]
    r,c=bottom,right
    while r>=top or c>=right:
        if inp[r][c]!=0: seq.append(inp[r][c])
        r-=1; c-=1
    # continue until we pass the bbox
    while len(seq)<=max(H,W):
        r-=1; c-=1
        if r<0 or c<0: break
        if inp[r][c]!=0: seq.append(inp[r][c])
    return seq,len(inp)
